// ============================================================
// StageSection — Collapsible Pipeline Stage (SA-015)
// ============================================================

import { useState } from 'react';
import { Badge, Card } from '@app/components';
import type { PipelineStage, StageData } from '../hooks/usePipeline';
import { PL_STAGE_LABELS, PL_STAGE_COLORS } from '../hooks/usePipeline';
import { PipelineRow } from './PipelineRow';

interface StageSectionProps {
  data: StageData;
  collapsed: boolean;
  onToggleCollapse: () => void;
  onMoveStage: (jobId: string, newStage: PipelineStage) => void;
  onConfirmSignal: (signalId: string, action: string, correctedStage?: string) => void;
  onUnsave: (jobId: string) => void;
  onSetTrackingMode: (jobId: string, mode: string) => void;
  onOpenModal: (jobId: string) => void;
}

export function StageSection({
  data, collapsed, onToggleCollapse,
  onMoveStage, onConfirmSignal, onUnsave, onSetTrackingMode, onOpenModal,
}: StageSectionProps) {
  const [dragOver, setDragOver] = useState(false);

  const matchText = data.minMatch != null && data.maxMatch != null && data.medianMatch != null
    ? `Match: ${data.minMatch}% – ${data.medianMatch}% – ${data.maxMatch}%`
    : null;

  // ── Drag-and-drop handlers ──
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setDragOver(true);
  };

  const handleDragLeave = () => {
    setDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const entryId = e.dataTransfer.getData('text/pipeline-entry-id');
    const fromStage = e.dataTransfer.getData('text/pipeline-from-stage');
    if (entryId && fromStage !== data.stage) {
      onMoveStage(entryId, data.stage);
    }
  };

  return (
    <Card
      variant="outline"
      padding="none"
      className={`overflow-hidden transition-all ${dragOver ? 'ring-2 ring-accent/50 bg-accent/5' : ''}`}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      {/* Stage header */}
      <button
        type="button"
        onClick={onToggleCollapse}
        className="w-full flex items-center gap-2.5 px-4 py-3 hover:bg-bg-hover/50 transition-colors select-none"
      >
        {/* Collapse chevron */}
        <span className={`text-[10px] text-text-faint transition-transform ${collapsed ? '' : 'rotate-90'}`}>
          ▶
        </span>

        {/* Stage color dot */}
        <span
          className="w-2.5 h-2.5 rounded-full flex-shrink-0"
          style={{ backgroundColor: PL_STAGE_COLORS[data.stage] }}
        />

        {/* Stage label */}
        <span className="text-[13px] font-bold text-text">
          {PL_STAGE_LABELS[data.stage]}
        </span>

        {/* Count */}
        <Badge variant="default" size="sm">
          {data.items.length}
        </Badge>

        {/* Signal badge */}
        {data.pendingSignalCount > 0 && (
          <Badge variant="info" size="sm" dot>
            {data.pendingSignalCount} signal{data.pendingSignalCount > 1 ? 's' : ''} pending
          </Badge>
        )}

        {/* Match range (right-aligned) */}
        {matchText && (
          <span className="ml-auto text-[10px] text-text-faint">
            {matchText}
          </span>
        )}
      </button>

      {/* Stage body */}
      {!collapsed && (
        <div className="border-t border-border">
          {data.items.length === 0 ? (
            <div className="py-6 text-center text-xs text-text-faint">
              No jobs in this stage
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="border-b border-border bg-bg-input/50">
                    <th className="w-4 py-1.5 px-1" />
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Title</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Company</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Resume</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Filters</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Discovered</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Applied</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Days</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Activity</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Match</th>
                    <th className="py-1.5 px-3 text-[10px] font-semibold text-text-faint uppercase tracking-[0.5px]">Move</th>
                    <th className="w-8 py-1.5 px-1" />
                  </tr>
                </thead>
                <tbody>
                  {data.items.map(item => (
                    <PipelineRow
                      key={item.id}
                      item={item}
                      stage={data.stage}
                      onMoveStage={onMoveStage}
                      onConfirmSignal={onConfirmSignal}
                      onUnsave={onUnsave}
                      onSetTrackingMode={onSetTrackingMode}
                      onOpenModal={onOpenModal}
                    />
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </Card>
  );
}

export default StageSection;
